/* From Uiverse.io by eduardo-amaro-maciel - Tags: card, scroll snap, dynamic */
.__UIV_SCOPE__ .scroll-1::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.__UIV_SCOPE__ .scroll-1::-webkit-scrollbar-thumb {
  border-radius: 20px;
  background: #888;
}

.__UIV_SCOPE__ .container * {
  box-sizing: border-box;
  padding: 0;
  margin: 0;
  color: #fff;
}

.__UIV_SCOPE__ .container {
  display: flex;
  overflow-x: scroll;
  padding: 24px;
  width: 300px;
  scroll-snap-type: x mandatory;
  scroll-padding-top: 24px;
  border-radius: 8px;
  gap: 20px;
}

.__UIV_SCOPE__ .container .card {
  flex: 0 0 100%;
  overflow: hidden;
  border-radius: 8px;
  background-color: #141414;
  scroll-snap-align: start;
}

.__UIV_SCOPE__ .card .card__image {
  flex: 1;
  height: 140px;
}

.__UIV_SCOPE__ .card:nth-child(1) .card__image {
  background-image: linear-gradient(
      to right top,
      #051937, 
      #004d7a, 
      #008793, 
      #00bf72, 
      #a8eb12
  );
}

.__UIV_SCOPE__ .card:nth-child(2) .card__image {
  background-image: linear-gradient(
    to right top, 
    #dc09a5, 
    #ce00b4, 
    #ba00c5, 
    #9c00d8, 
    #6f12eb
  );
}

.__UIV_SCOPE__ .card:nth-child(3) .card__image {
  background-image: linear-gradient(
    to right top, 
    #dc1009, 
    #e55f00, 
    #e49200, 
    #dac000, 
    #c7eb12
  );
}

.__UIV_SCOPE__ .card .card__content {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 20px;
}

.__UIV_SCOPE__ .card .card__content .card__title {
  font-size: 32px;
  color: #fff;
  text-transform: capitalize;
}

.__UIV_SCOPE__ .card .card__content .card__describe {
  color: #fff;
  font-size: 16px;
}
